script:
// A greeting for the person: no picture to configure, nothing to go missing.
// Their own record comes through seal_hrms (staff may not look themselves up by login).
let box = $(root_element).find(".ess-greeting");
let hour = new Date().getHours();
let part = hour < 12 ? __("Good morning") : hour < 17 ? __("Good afternoon") : __("Good evening");
let first = (frappe.session.user_fullname || "").split(" ")[0];
box.find(".ess-greeting-hello").text(first ? part + ", " + first : part);

frappe
	.xcall("seal_hrms.seal_hrms.task_assignment_access.my_employee_fields", {
		fields: ["first_name", "designation", "department"],
	})
	.then((me) => {
		if (!me || !me.first_name) return;
		box.find(".ess-greeting-hello").text(part + ", " + me.first_name);
		box.find(".ess-greeting-role").text([me.designation, me.department].filter(Boolean).join(" · "));
	})
	.catch(() => {});

style:
.ess-greeting {
	padding: var(--padding-md) 0 var(--padding-sm);
}

.ess-greeting-hello {
	font-size: 2rem;
	line-height: 1.2;
	font-weight: 600;
	color: var(--heading-color);
}

.ess-greeting-role {
	margin-top: 4px;
	font-size: var(--text-lg);
	color: var(--text-muted);
}

.ess-flow { padding: 4px 2px; }
.ess-flow__intro h4 { margin: 0 0 6px; }
.ess-flow__intro p { color: var(--text-muted); margin: 0 0 16px; max-width: 62em; }

/* Eleven tiles, so they wrap into rows rather than one long rail. */
.ess-flow__rail { display: flex; align-items: stretch; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.ess-flow__step {
  flex: 1 1 200px; min-width: 190px; display: flex; gap: 10px;
  border: 1px solid var(--border-color); border-radius: var(--border-radius-md);
  padding: 10px 12px; background: var(--card-bg);
}
/* The icon sits where the step number sits on the flow blocks, so the two read
   as the same family even though these are areas rather than steps. */
.ess-flow__num {
  flex: 0 0 22px; height: 22px; border-radius: 50%;
  background: var(--control-bg); font-size: 13px; line-height: 1;
  display: flex; align-items: center; justify-content: center;
}
.ess-flow__body { display: flex; flex-direction: column; line-height: 1.4; }
.ess-flow__body span { color: var(--text-muted); font-size: .85em; margin-top: 2px; }

.ess-flow__aside { display: flex; flex-wrap: wrap; gap: 8px; }
.ess-flow__card {
  flex: 1 1 260px; display: flex; flex-direction: column;
  border-left: 3px solid var(--border-color); padding: 4px 12px;
}
.ess-flow__card span { color: var(--text-muted); font-size: .85em; margin-top: 2px; }

/* Tiles are links: inherit text colour, lift on hover, keyboard focusable.
   Every colour below is a theme variable — no literals — so the whole block
   re-tints when the theme changes. `--primary-color` is the darker shade of
   the theme colour (teal-900 on the teal theme), which is what the highlight
   and borders use; `--primary` alone is too light to read as an edge. */
a.ess-flow__step, a.ess-flow__card {
  text-decoration: none; color: inherit;
  transition: border-color .12s, background .12s, transform .12s;
}
a.ess-flow__step:hover, a.ess-flow__card:hover {
  border-color: var(--primary-color, var(--primary));
  background: var(--fg-hover-color, var(--control-bg));
  transform: translateY(-1px);
}
/* Badge lightens on hover instead of filling with colour. `--fg-color` is the
   page surface — white on light themes, the dark surface on dark ones — so it
   reads as white where you would expect white, without hardcoding it. No text
   colour needed: the badge holds an emoji, which carries its own colours. */
a.ess-flow__step:hover .ess-flow__num { background: var(--fg-color); }
a.ess-flow__step:focus-visible, a.ess-flow__card:focus-visible {
  outline: 2px solid var(--primary-color, var(--primary)); outline-offset: 2px;
}
